css:
.optic-switch {
  display: inline-flex;
  position: relative;
  font-size: 10px;
  width: 20em;
  height: 7em;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

.optic-input {
  display: none;
}

.optic-ambient {
  position: absolute;
  top: -3em;
  left: -2em;
  width: 11em;
  bottom: -3em;
  background-color: rgba(255, 59, 48, 0.12);
  border-radius: 50%;
  filter: blur(2.5em);
  transition:
    transform 0.7s cubic-bezier(0.85, 0, 0.15, 1),
    background-color 0.5s ease;
  pointer-events: none;
  z-index: 0;
}

.optic-input:checked ~ .optic-ambient {
  transform: translateX(13em);
  background-color: rgba(0, 212, 255, 0.2);
}

.optic-track {
  position: absolute;
  top: 0px;
  left: 0px;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, #e2e8f0, #f8fafc);
  border-radius: 3.5em;
  box-shadow:
    inset 0px 0.2em 0.6em rgba(0, 0, 0, 0.1),
    inset 0px -0.1em 0.2em rgba(255, 255, 255, 0.8),
    0px 0.5em 1em rgba(0, 0, 0, 0.05);
  overflow: hidden;
  z-index: 1;
  transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.optic-switch:active .optic-track {
  transform: scale(0.97);
}

.optic-rim {
  position: absolute;
  top: 0px;
  left: 0px;
  right: 0px;
  bottom: 0px;
  border-radius: 3.5em;
  border: 0.1em solid #ffffff;
  pointer-events: none;
  z-index: 10;
}

.optic-fiber {
  position: absolute;
  top: 3.35em;
  left: 3.5em;
  right: 3.5em;
  height: 0.3em;
  background-color: #cbd5e1;
  border-radius: 0.15em;
  box-shadow:
    inset 0px 0.1em 0.2em rgba(0, 0, 0, 0.15),
    0px 0.1em 0.1em rgba(255, 255, 255, 0.9);
  z-index: 1;
  overflow: hidden;
}

.optic-fiber-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #007aff, #00d4ff);
  border-radius: 0.15em;
  box-shadow: 0px 0px 0.8em rgba(0, 212, 255, 0.6);
  transition: width 0.7s cubic-bezier(0.85, 0, 0.15, 1);
}

.optic-input:checked ~ .optic-track .optic-fiber .optic-fiber-fill {
  width: 100%;
}

.optic-node {
  position: absolute;
  top: 2.5em;
  width: 2em;
  height: 2em;
  border-radius: 50%;
  background-color: #f1f5f9;
  box-shadow:
    inset 0px 0.1em 0.3em rgba(0, 0, 0, 0.1),
    0px 0.1em 0.1em rgba(255, 255, 255, 1);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}

.optic-node-left {
  left: 2.5em;
}

.optic-node-right {
  right: 2.5em;
}

.optic-node-dot {
  width: 0.4em;
  height: 0.4em;
  border-radius: 50%;
  background-color: #94a3b8;
  box-shadow: inset 0px 0.1em 0.1em rgba(0, 0, 0, 0.1);
  transition:
    background-color 0.4s ease,
    box-shadow 0.4s ease;
}

.optic-input:not(:checked) ~ .optic-track .optic-node-left .optic-node-dot {
  background-color: #ff3b30;
  box-shadow: 0px 0px 0.5em rgba(255, 59, 48, 0.6);
}

.optic-input:checked ~ .optic-track .optic-node-right .optic-node-dot {
  background-color: #00d4ff;
  box-shadow: 0px 0px 0.5em rgba(0, 212, 255, 0.6);
}

.optic-shuttle {
  position: absolute;
  top: 0.5em;
  left: 0.5em;
  width: 6em;
  height: 6em;
  z-index: 5;
  transition: transform 0.7s cubic-bezier(0.85, 0, 0.15, 1);
  display: flex;
  align-items: center;
  justify-content: center;
}

.optic-input:checked ~ .optic-track .optic-shuttle {
  transform: translateX(13em);
}

.optic-chassis {
  position: absolute;
  top: 0px;
  left: 0px;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: linear-gradient(135deg, #ffffff, #e2e8f0);
  box-shadow:
    inset 0px 0.1em 0.2em rgba(255, 255, 255, 1),
    inset 0px -0.2em 0.5em rgba(0, 0, 0, 0.05),
    0px 0.3em 0.6em rgba(0, 0, 0, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.7s cubic-bezier(0.85, 0, 0.15, 1);
}

.optic-input:checked ~ .optic-track .optic-shuttle .optic-chassis {
  transform: rotate(360deg);
}

.optic-mark {
  position: absolute;
  background-color: #cbd5e1;
  border-radius: 0.15em;
  box-shadow:
    inset 0px 0.1em 0.2em rgba(0, 0, 0, 0.1),
    0px 0.1em 0.1em rgba(255, 255, 255, 1);
}

.optic-mark-vertical {
  width: 0.3em;
  height: 1em;
}

.optic-mark-horizontal {
  width: 1em;
  height: 0.3em;
}

.optic-m1 {
  top: 0.4em;
}
.optic-m2 {
  bottom: 0.4em;
}
.optic-m3 {
  left: 0.4em;
}
.optic-m4 {
  right: 0.4em;
}

.optic-aperture {
  width: 3.5em;
  height: 3.5em;
  border-radius: 50%;
  background-color: #f8fafc;
  border: 0.2em solid #e2e8f0;
  box-shadow:
    inset 0px 0.3em 0.6em rgba(0, 0, 0, 0.1),
    0px 0.1em 0.2em rgba(255, 255, 255, 1);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 2;
  transition:
    border-color 0.5s ease,
    box-shadow 0.5s ease;
  overflow: hidden;
}

.optic-input:checked
  ~ .optic-track
  .optic-shuttle
  .optic-chassis
  .optic-aperture {
  border-color: rgba(0, 212, 255, 0.4);
  box-shadow:
    inset 0px 0.3em 0.6em rgba(0, 0, 0, 0.1),
    0px 0px 0.8em rgba(0, 212, 255, 0.2);
}

.optic-pupil {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background-color: #ff3b30;
  box-shadow:
    0px 0px 0.4em rgba(255, 59, 48, 0.6),
    inset 0px 0px 0.2em rgba(255, 255, 255, 0.6);
  border: 1.5em solid #ffffff;
  transition:
    border-width 0.6s cubic-bezier(0.85, 0, 0.15, 1),
    background-color 0.4s ease,
    box-shadow 0.4s ease;
  box-sizing: border-box;
}

.optic-input:checked
  ~ .optic-track
  .optic-shuttle
  .optic-chassis
  .optic-aperture
  .optic-pupil {
  border-width: 0.3em;
  background-color: #00d4ff;
  box-shadow:
    0px 0px 1.2em 0.3em rgba(0, 212, 255, 0.6),
    inset 0px 0px 0.6em rgba(255, 255, 255, 0.9);
}

.optic-lens {
  position: absolute;
  top: 0px;
  left: 0px;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: radial-gradient(
    circle at 35% 25%,
    rgba(255, 255, 255, 0.6) 0%,
    transparent 40%,
    rgba(0, 0, 0, 0.08) 100%
  );
  z-index: 3;
  pointer-events: none;
}
